using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. Strongly-typed metadata via GetTypeInfo<T>() ---
// Use a source-generated context so metadata is available for Person.
var options = new JsonSerializerOptions { TypeInfoResolver = AppJsonContext.Default };

// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no casting needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person — kind: {personInfo.Kind}, type: {personInfo.Type.Name}");

// Quick round-trip to prove the metadata works.
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-tripped: {p}");

// --- 2. Probe without throwing via TryGetTypeInfo ---
// Person is in the context → expect true.
bool havePerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? maybePerson);
Console.WriteLine($"\nTryGetTypeInfo(Person)  → found={havePerson}, info={maybePerson?.Type.Name}");

// DateTime is NOT in our context → expect false, no exception.
bool haveDateTime = options.TryGetTypeInfo(typeof(DateTime), out JsonTypeInfo? maybeDateTime);
Console.WriteLine($"TryGetTypeInfo(DateTime) → found={haveDateTime}, info={maybeDateTime?.Type.Name ?? "(null)"}");

// Types
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class AppJsonContext : JsonSerializerContext;

